    """Extended monad operations."""

    @classmethod
    def pure(cls, value: T) -> "TokenMonad[T]":
        return cls(value)

    def ap(self, func_wrapped: "TokenMonad[Callable[[T], Any]]") -> "TokenMonad[Any]":
