sealed abstract class TokenType(val value: String) extends Product with Serializable

object TokenType {
  case object STRING extends TokenType("string")
  case object NUMERIC extends TokenType("numeric")
  case object TEMPORAL extends TokenType("temporal")
  case object STRUCTURED extends TokenType("structured")
  case object BINARY extends TokenType("binary")
  case object NULL extends TokenType("null")
}

// ============================================================================
// Core token classes
// ============================================================================

final case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {
  def withMetadata(kv: (String, Any)*): Token = copy(metadata = metadata ++ kv.toMap)
}

final class MutableTokenBatch {
  private val buffer = mutable.ListBuffer.empty[Token]
  private var processed = false

  def tokens: List[Token] = buffer.toList

  def add(token: Token): Unit = {
    if (processed) throw new RuntimeException("Batch already processed")
    buffer += token
  }

  def markProcessed(): Unit = {
    processed = true
  }
}

// ============================================================================
// Generic container classes
// ============================================================================

final class TokenContainer[+T](items: Seq[T]) {
  private val data: Vector[T] = items.toVector

  def getAll: Vector[T] = data

  def size: Int = data.size

  def mapTokens(func: T => String): List[String] = data.map(func).toList
}

final class TokenSink[-T] {
  private val received = mutable.ListBuffer.empty[Any]

  def receive(item: T): Unit = received += item

  def drain(): List[Any] = {
    val result = received.toList
    received.clear()
    result
  }
}

final class BivariantHandler[T](default: T) {
  private var value: T = default

  def get: T = value

  def set(next: T): Unit = {
    value = next
  }

  def transform(func: T => T): T = {
    value = func(value)
    value
  }
}

