  def tokenize(value: String): Token = tokenize(StringOrBytes.Str(value))

  def tokenize(value: Array[Byte]): Token = tokenize(StringOrBytes.Bytes(value))

  override def tokenize(value: StringOrBytes): Token = {
    val strValue = value match {
      case StringOrBytes.Str(v)   => v
      case StringOrBytes.Bytes(b) => new String(b, charset)
