    case v: String => Some(JsonString(v))
    case v: Boolean => Some(JsonBool(v))
    case v: Int => Some(JsonNumber(BigDecimal(v)))
    case v: Long => Some(JsonNumber(BigDecimal(v)))
    case v: Double => Some(JsonNumber(BigDecimal.decimal(v)))
    case v: Float => Some(JsonNumber(BigDecimal.decimal(v.toDouble)))
    case v: BigDecimal => Some(JsonNumber(v))
    case v: BigInt => Some(JsonNumber(BigDecimal(v)))
    case v: Seq[_] =>
      val converted = v.flatMap(fromAny)
      if (converted.size == v.size) Some(JsonArray(converted.toVector)) else None
    case v: Map[_, _] =>
      val converted = v.collect {
        case (k: String, inner) => fromAny(inner).map(k -> _)
      }.flatten.toMap
      if (converted.size == v.size) Some(JsonObject(converted)) else None
    case _ => None
  }

  def toCirce(value: JsonValue): Json = value match {
    case JsonString(v) => Json.fromString(v)
    case JsonNumber(v) => Json.fromBigDecimal(v)
    case JsonBool(v)   => Json.fromBoolean(v)
    case JsonNull      => Json.Null
    case JsonArray(values) => Json.arr(values.map(toCirce): _*)
    case JsonObject(values) =>
      Json.obj(values.map { case (k, v) => k -> toCirce(v) }.toSeq: _*)
  }

  def render(value: JsonValue, pretty: Boolean): String = {
    val json = toCirce(value)
    if (pretty) json.spaces2 else json.noSpaces
  }
}

final class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenize(value: JsonValue): Token = {
    val jsonStr = JsonValue.render(value, pretty)
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList

    def step(current: JsonValue, remaining: List[String]): Option[JsonValue] =
      remaining match {
        case Nil => Some(current)
        case head :: tail =>
          current match {
            case JsonValue.JsonObject(values) => values.get(head).flatMap(step(_, tail))
            case JsonValue.JsonArray(values) if head.forall(_.isDigit) =>
              val idx = head.toInt
              values.lift(idx).flatMap(step(_, tail))
            case _ => None
          }
      }

    step(value, parts).map(tokenize)
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split("\\.").toList

    def step(current: Json, remaining: List[String]): Option[Json] =
      remaining match {
        case Nil => Some(current)
        case head :: tail =>
          current.arrayOrObject(
            None,
            arr => if (head.forall(_.isDigit)) arr.lift(head.toInt).flatMap(step(_, tail)) else None,
            obj => obj.apply(head).flatMap(step(_, tail))
          )
      }

    step(value, parts).map(tokenize)
  }
}

// ============================================================================
// Whitespace tokenizer - basic text tokenization
// ============================================================================

final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def stripEdgePunctuation(word: String): String = {
    val leadingStripped = word.dropWhile(punctuation.contains)
    leadingStripped.reverse.dropWhile(punctuation.contains).reverse
  }

  private def processToken(word: String): Option[String] = {
    val cleaned = if (stripPunctuation) stripEdgePunctuation(word) else word
    val lowered = if (lowercase) cleaned.toLowerCase else cleaned

    if (lowered.length < minLength) return None

    val trimmed = maxLength match {
      case Some(limit) if lowered.length > limit => lowered.take(limit)
      case _ => lowered
    }

    if (trimmed.isEmpty) None else Some(trimmed)
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").toList.filter(_.nonEmpty)
    val tokens = mutable.ListBuffer.empty[Token]

    words.zipWithIndex.foreach { case (word, idx) =>
      processToken(word).foreach { processed =>
        tokens += Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> idx, "original" -> word)
        )
      }
    }

    tokens.toList
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").toList.filter(_.nonEmpty)
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    words.foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

// ============================================================================
// Builder pattern with fluent interface
// ============================================================================

final class TokenizerBuilder[T] private () {
  private val normalizers = mutable.ListBuffer.empty[String => String]
  private val validators = mutable.ListBuffer.empty[T => Boolean]
  private val metadata = mutable.Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(kv: (String, Any)*): TokenizerBuilder[T] = {
    metadata ++= kv
    this
  }

  def build(): T => Token = {
    val normalizersSnapshot = normalizers.toList
    val validatorsSnapshot = validators.toList
    val metadataSnapshot = metadata.toMap

    value => {
      validatorsSnapshot.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      var strValue = value.toString
      normalizersSnapshot.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, metadataSnapshot)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}

